import os,subprocess,time,datetime,signal
from pathlib import Path
W=Path('/home/linhao/Toolchain/development/llvm_autofdo_bolt_agent');D=W/'temp/profgen-host-verification/build'
def now():return datetime.datetime.now().astimezone().isoformat(timespec='seconds')
def sample():
 with (D/'resources.txt').open('a') as f:
  f.write(now()+'\n');f.flush()
  for cmd in [['free','-m'],['uptime']]:subprocess.run(cmd,stdout=f,stderr=subprocess.STDOUT)
def stop(sig,frame):raise KeyboardInterrupt(str(sig))
signal.signal(signal.SIGTERM,stop);signal.signal(signal.SIGINT,stop)
rc='NOT_STARTED';p=None;start=now()
try:
 for arch,conf in [('aarch64','gbs_rpi5_image.conf'),('armv7l','gbs_rpi4_spike.conf')]:
  heavy=subprocess.check_output(['ps','-eo','comm='],text=True).splitlines()
  if any(s.strip() in ['ninja','make','gbs','depanneur','clang','clang-22','ld.lld'] for s in heavy):raise RuntimeError('Other heavy build present; not starting')
  sample();env=os.environ.copy();env.update(HOME=str(W/'temp/gbs-home'),GIT_CONFIG_NOSYSTEM='1')
  cmd=['setsid','--wait','nice','-n','19','ionice','-c3','gbs','-c',str(W/'temp/gbs'/conf),'build','-A',arch,'--threads','1','--define','_smp_mflags -j'+str(max(1,os.cpu_count()//2))]
  t=now();print('BUILD_START',arch,t,repr(cmd),flush=True)
  with (D/(arch+'.log')).open('w') as f:
   p=subprocess.Popen(cmd,cwd=W/'temp/profgen-host-verification/package',env=env,stdout=f,stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL);n=time.monotonic()+600
   while p.poll() is None:
    time.sleep(2)
    if time.monotonic()>=n:sample();n+=600
   rc=p.wait()
  end=now();(D/(arch+'.status')).write_text(f'START {t}\nEND {end}\nGBS_EXIT {rc}\nALL-END {end} '+('OK' if rc==0 else 'FAILED')+'\n');print((D/(arch+'.status')).read_text(),flush=True)
  if rc:raise RuntimeError('GBS failed: '+arch)
  # Save BUILD products before another build can reuse the scratch tree.
  import shutil
  root=W/('temp/GBS-ROOT-RPI5-SPIKE' if arch=='aarch64' else 'temp/GBS-ROOT-RPI4-SPIKE')/'local/BUILD-ROOTS'/('scratch.'+arch+'.0')
  saved=D/arch;saved.mkdir(exist_ok=True)
  for base in [root/'home/abuild/rpmbuild/BUILD/host-profile-check-1.0',W/'temp/profgen-host-verification/package']:
   for name in ['libhostcheck.so','libhostprobe.so']:
    if (base/name).is_file():shutil.copyfile(base/name,saved/name)
 sample();(D/'status').write_text(f'START {start}\nALL-END {now()} OK\n')
except BaseException as e:
 if p is not None and p.poll() is None:
  os.killpg(p.pid,signal.SIGTERM);rc=p.wait()
 (D/'status').write_text(f'START {start}\nGBS_EXIT {rc}\nREASON {e!r}\nALL-END {now()} FAILED\n');print((D/'status').read_text(),flush=True)

